    host = urlparse(url).hostname
    if not host:
        raise PermissionError(f"Could not determine hostname for URL: {url}")
    patterns = self.settings.allowed_host_patterns
    if "*" in patterns:
        return
    if not patterns or patterns == ["*"]:
