async def _wait_for_ws_endpoint(self, container, endpoint_file: Path) -> str:
    for _ in range(max(1, self.settings.isolated_browser_wait_timeout_seconds * 4)):
        await asyncio.to_thread(container.reload)
        status = str(getattr(container, "status", "") or container.attrs.get("State", {}).get("Status", ""))
        if status in {"exited", "dead"}:
            logs = self._container_logs(container)
            raise RuntimeError(
                f"Isolated browser container {container.name} exited before Playwright endpoint was ready. {logs}"
            )
        if endpoint_file.exists():
            endpoint = endpoint_file.read_text(encoding="utf-8").strip()
            if endpoint:
                return endpoint
        await asyncio.sleep(0.25)
    logs = self._container_logs(container)
    raise RuntimeError(
        f"Timed out waiting for isolated browser endpoint file {endpoint_file}. {logs}"
    )

async def startup(self) -> None:
    self._stop_event.clear()
    if self.settings.cleanup_on_startup:
        await self.run_cleanup()
    if self.settings.cleanup_interval_seconds > 0:
        self._task = asyncio.create_task(self._run_loop(), name="maintenance-cleanup-loop")

async def _run_loop(self) -> None:
    while not self._stop_event.is_set():
        try:
            await asyncio.wait_for(self._stop_event.wait(), timeout=self.settings.cleanup_interval_seconds)
        except asyncio.TimeoutError:
            await self.run_cleanup()

def _protected_roots(self) -> list[Path]:
    protected: list[Path] = [Path(self.settings.auth_root).resolve() / "profiles"]
    for session in self.session_provider():
        for attr in ("artifact_dir", "upload_dir", "auth_dir"):
            value = getattr(session, attr, None)
            if value is None:
                continue
            protected.append(Path(value).resolve())
    return protected

